            code = (
                "from pxr import Sdf\n"
                "stage = hou.pwd().editableStage()\n"
                f"prim = stage.GetPrimAtPath({repr(prim_path)})\n"
                "if prim:\n"
                f"    attr = prim.GetAttribute({repr(attr_name)})\n"
